184	/**
185	 * One hook path, against `base`.
186	 *
187	 * An already-absolute path is left alone, so an adopter who names one gets what they
188	 * asked for rather than a path joined onto a path. Anything that is not a string is
189	 * returned untouched: this resolves paths, and reporting that one is the wrong type
190	 * belongs to the core, which says so with the file in front of it.
191	 */
192	function absolutePath(script: unknown, base: string): unknown {
193	  if (typeof script !== "string" || script.length === 0) return script;
194	  if (isAbsolute(script)) return script;
195	  // Posix separators: this is written for a Linux runner, and a Windows-style
196	  // separator would reach the core as part of the filename.
197	  // The base is made absolute first, rather than resolving base and script
198	  // together: resolving both rewrites an already-absolute POSIX base onto the
199	  // current drive on Windows, where the tests for this also run.
200	  const from = isAbsolute(base) ? base : resolve(base);
201	  return join(from, script).split("\\").join("/");
202	}
